import{_ as e,o as d,c as o,a3 as c}from"./chunks/framework.BLaSdaBb.js";const h=JSON.parse('{"title":"系统设置","description":"","frontmatter":{},"headers":[],"relativePath":"backend/settings.md","filePath":"backend/settings.md","lastUpdated":1786258579000}'),a={name:"backend/settings.md"};function r(s,t,i,n,l,g){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h1><p>「系统设置」这一组页面管的是<strong>运行期可调、不需要改代码重新部署的东西</strong>：菜单、字典、参数、业务编号、缓存、服务监控、版本。本页按页面逐项说明数据模型与使用要点。</p><p>对应菜单目录 <code>/setting</code>（部分页面在 <code>/file</code> 目录下）。</p><h2 id="菜单管理-setting-menu" tabindex="-1">菜单管理（<code>/setting/menu</code>） <a class="header-anchor" href="#菜单管理-setting-menu" aria-label="Permalink to &quot;菜单管理（`/setting/menu`）&quot;">​</a></h2><p>页面能看到并微调 <code>SysMenu</code> 表，但<strong>它不是事实源</strong>。</p><div class="danger custom-block"><p class="custom-block-title">菜单的事实源在后端代码里</p><p>菜单、路由、组件路径、权限码、国际化键统一由 <code>Application/Pages/PageRegistry.cs</code> 登记，<code>SaasMenuSeeder</code>（<code>Order=25</code>）据此播种到 <code>SysMenu</code>。</p><p><strong>新增/修改菜单要改 <code>PageRegistry</code> 并重新播种</strong>，在页面上手改会在下次播种时被覆盖或产生漂移。菜单管理页的定位是查看结构、调整排序与显隐，不是维护入口。</p></div><p>关键机制见 <a href="./introduction#菜单-后端单一事实源">后端架构 · 菜单</a>。</p><h2 id="数据字典-setting-dict" tabindex="-1">数据字典（<code>/setting/dict</code>） <a class="header-anchor" href="#数据字典-setting-dict" aria-label="Permalink to &quot;数据字典（`/setting/dict`）&quot;">​</a></h2><p>两级结构：</p><table tabindex="0"><thead><tr><th>实体</th><th>关键字段</th></tr></thead><tbody><tr><td><code>SysDict</code></td><td><code>DictCode</code>（编码）、<code>DictName</code>、<code>DictType</code>、<code>IsBuiltIn</code>（内置不可删）、<code>Status</code>、<code>Sort</code></td></tr><tr><td><code>SysDictItem</code></td><td><code>DictId</code>、<code>ParentId</code>（<strong>支持树形字典项</strong>）、<code>ItemCode</code>、<code>ItemName</code>、<code>ItemValue</code>、<code>Metadata</code>、<code>IsDefault</code>、<code>Status</code>、<code>Sort</code></td></tr></tbody></table><p>用途是给表单、搜索下拉提供<strong>可运营维护的选项集</strong>（如客户等级、合同类型）。</p><div class="tip custom-block"><p class="custom-block-title">字典 vs 枚举：怎么选</p><ul><li><strong>枚举</strong>（C# <code>enum</code>）：值集由<strong>代码</strong>决定，改动要发版。标签的事实源是后端枚举元数据（<code>Enums.{culture}.json</code>），天然多语言。适合状态机、类型判别这类参与业务逻辑的值。</li><li><strong>字典</strong>（<code>SysDict</code>）：值集由<strong>运营</strong>维护，随时增删。适合业务分类、标签这类纯数据的值。</li></ul><p>前端 Schema 字段用 <code>dictionaryCode</code> 声明，两者的取值路径是统一的——但<strong>别把参与 <code>switch</code> 判断的值放进字典</strong>，运营删一条就会打穿代码分支。</p></div><p>字典项树走 Redis 缓存（<code>basicapp:saas:configuration:dict-tree</code>），写侧改完必须调 <code>InvalidateDictionaryAsync()</code>。</p><h2 id="参数配置-setting-config" tabindex="-1">参数配置（<code>/setting/config</code>） <a class="header-anchor" href="#参数配置-setting-config" aria-label="Permalink to &quot;参数配置（`/setting/config`）&quot;">​</a></h2><p><code>SysConfig</code> 是<strong>运行期系统参数</strong>，与 <code>appsettings.json</code> 是两套东西：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>ConfigKey</code> / <code>ConfigValue</code> / <code>DefaultValue</code></td><td>键、当前值、默认值</td></tr><tr><td><code>ConfigGroup</code></td><td>分组，用于页面归类</td></tr><tr><td><code>ConfigType</code></td><td>配置类型（如 <code>Feature</code> 功能开关）</td></tr><tr><td><code>DataType</code></td><td>值的数据类型（<code>String</code> / 数值 / 布尔 等），前端据此渲染控件</td></tr><tr><td><code>IsBuiltIn</code></td><td>内置参数不可删</td></tr><tr><td><strong><code>IsEncrypted</code></strong></td><td><strong>加密存储</strong>——密钥类参数落库前加密，读侧不回显明文</td></tr><tr><td><code>Status</code> / <code>Sort</code> / <code>Remark</code></td><td>常规</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">什么该放 appsettings、什么该放 <code>SysConfig</code></p><ul><li><strong><code>appsettings</code></strong>：基础设施连接与启动期就要用的东西（数据库连接串、Redis、JWT 密钥、监听端口）。改了要重启。</li><li><strong><code>SysConfig</code></strong>：业务开关与运营参数（是否开放注册、单页默认条数、某功能灰度开关）。改了立即生效（走缓存失效），且<strong>可按租户覆盖</strong>。</li></ul><p>判断标准：这个值需要在运行期由管理员改吗？需要 → <code>SysConfig</code>。</p></div><p>配置值走缓存（<code>basicapp:saas:config:value</code>），写侧调 <code>InvalidateConfigurationAsync(configKey?)</code>。</p><h2 id="业务编号-setting-numbering" tabindex="-1">业务编号（<code>/setting/numbering</code>） <a class="header-anchor" href="#业务编号-setting-numbering" aria-label="Permalink to &quot;业务编号（`/setting/numbering`）&quot;">​</a></h2><p>给业务单据发号（订单号、合同号、工单号），保证<strong>同一周期内单调递增且不重复</strong>。</p><p><code>SysNumberingRule</code> 的构成：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>默认</th></tr></thead><tbody><tr><td><code>RuleCode</code> / <code>RuleName</code></td><td>规则编码与名称</td><td>—</td></tr><tr><td><code>Prefix</code></td><td>前缀，如 <code>SO</code></td><td>—</td></tr><tr><td><code>Separator</code></td><td>分隔符</td><td><code>-</code></td></tr><tr><td><code>DateFormat</code></td><td>日期段格式</td><td><code>yyyyMMdd</code></td></tr><tr><td><code>SerialLength</code></td><td>序号位数（左补零）</td><td><code>4</code></td></tr><tr><td><code>ResetCycle</code></td><td><strong>重置周期</strong>：按日/月/年/不重置</td><td><code>Daily</code></td></tr><tr><td><code>TimeZoneId</code></td><td><strong>按哪个时区判定周期边界</strong></td><td><code>UTC</code></td></tr><tr><td><code>AllowTenantUse</code></td><td>是否允许租户使用该规则</td><td><code>false</code></td></tr><tr><td><code>CurrentValue</code> / <code>CurrentPeriod</code> / <code>CurrentPeriodOrdinal</code></td><td>当前值与周期游标（运行时状态）</td><td>—</td></tr><tr><td><code>HasAllocated</code></td><td>是否已发过号</td><td>—</td></tr></tbody></table><p>生成结果形如 <code>SO-20260804-0001</code>。</p><div class="warning custom-block"><p class="custom-block-title">三个容易出事的点</p><ol><li><strong><code>TimeZoneId</code> 决定周期边界</strong>。设成 <code>UTC</code> 而业务在东八区，那么每天 08:00 才换号段——上线前对齐清楚。</li><li><strong><code>ResetCycle</code> 不能往回退</strong>（如从「按日」改成「按年」），会导致已发出的号段与新周期语义冲突，服务层会拒绝。</li><li><strong>改规则会影响历史号的可读性</strong>，但不会回溯改已发的号。<code>SysNumberingAllocation</code> 记录每次分配，可用于追溯。</li></ol></div><p>发号在事务内以「单调翻转 → 递增 → 读回」完成，不加进程内锁；并发下靠数据库保证。</p><h2 id="缓存管理-setting-cache" tabindex="-1">缓存管理（<code>/setting/cache</code>） <a class="header-anchor" href="#缓存管理-setting-cache" aria-label="Permalink to &quot;缓存管理（`/setting/cache`）&quot;">​</a></h2><p>查看与清理 Redis 缓存。日常用途有两个：</p><ul><li><strong>排障</strong>：怀疑「改完不生效」时，先看缓存里是不是旧值。</li><li><strong>应急</strong>：确认是失效逻辑漏了，可以手工清一次先恢复业务，再回头修代码。</li></ul><div class="danger custom-block"><p class="custom-block-title">手工清缓存是应急手段</p><p>手工清完问题消失，说明<strong>写侧漏调了失效方法</strong>——这是需要修的 bug，不是一次性故障。正确做法见 <a href="./caching#加一个新缓存的清单">缓存与异步</a>。</p></div><p>缓存键的命名规则、条目清单与失效器方法同样在那一页。</p><h2 id="服务监控-setting-server" tabindex="-1">服务监控（<code>/setting/server</code>） <a class="header-anchor" href="#服务监控-setting-server" aria-label="Permalink to &quot;服务监控（`/setting/server`）&quot;">​</a></h2><p><code>ServerAppService</code> 提供运行时信息可视化：CPU / 内存 / 磁盘 / GPU / 网络 / 主板 / .NET 运行时。</p><p>它读的是<strong>当前进程所在机器</strong>的信息。多实例部署时看到的是「你这次请求恰好打到的那个实例」，不是集群汇总——要做集群视图请接 OpenTelemetry 指标导出。配置与真实健康探测见<a href="./health-observability">健康检查与可观测性</a>。</p><h2 id="版本管理-setting-version" tabindex="-1">版本管理（<code>/setting/version</code>） <a class="header-anchor" href="#版本管理-setting-version" aria-label="Permalink to &quot;版本管理（`/setting/version`）&quot;">​</a></h2><p><code>SysVersion</code> 记录应用版本与数据库版本，配合框架的升级引擎：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>AppVersion</code> / <code>DbVersion</code></td><td>应用版本 / 数据库版本</td></tr><tr><td><code>MinSupportVersion</code></td><td>允许升级的最低来源版本</td></tr><tr><td><code>IsUpgrading</code> / <code>UpgradeNode</code> / <code>UpgradeStartTime</code></td><td>升级中标记、执行节点、开始时间（多节点协调用）</td></tr></tbody></table><p>升级能力由配置节 <code>XiHan:Upgrade</code> 控制（分布式锁、主节点、维护模式等），见<a href="./upgrade">升级与迁移</a>。</p><div class="warning custom-block"><p class="custom-block-title">版本页只读，脚本才是迁移入口</p><p><code>SysVersion</code> 由升级引擎独占写入，管理端不提供手工改版本。结构和数据迁移放在 <code>WebHost/UpdateScripts/{version}.sql</code>；<code>DbInitializer</code> 只负责全新数据库建表，不会给已有表补列。当前 BasicApp 尚未调用升级执行入口，脚本不会仅因 <code>EnableAutoCheckOnStartup=true</code> 自动运行，详见<a href="./upgrade#当前结论">当前结论</a>。</p></div><h2 id="通道配置-邮件-短信-机器人" tabindex="-1">通道配置（邮件 / 短信 / 机器人） <a class="header-anchor" href="#通道配置-邮件-短信-机器人" aria-label="Permalink to &quot;通道配置（邮件 / 短信 / 机器人）&quot;">​</a></h2><p>这几个页面在同一菜单目录下，配置<strong>落库而非写 appsettings</strong>，因此可以按租户隔离、运行期热切换：</p><table tabindex="0"><thead><tr><th>页面</th><th>实体</th><th>说明</th></tr></thead><tbody><tr><td>邮件配置 <code>/setting/email-config</code></td><td><code>SysEmailConfig</code></td><td>SMTP 网关</td></tr><tr><td>短信配置 <code>/setting/sms-config</code></td><td><code>SysSmsConfig</code></td><td>短信网关</td></tr><tr><td>机器人配置 <code>/setting/bot-config</code></td><td><code>SysBotConfig</code></td><td>钉钉 / 飞书 / 企业微信 Webhook 机器人</td></tr><tr><td>Telegram 机器人 <code>/setting/telegram-bot</code></td><td><code>SysTelegramBot</code></td><td>多实例 Telegram Bot</td></tr></tbody></table><p>它们通过 <code>services.Replace(...)</code> 覆盖框架各 Bot 包的默认 <code>*ConfigStore</code>——框架侧读的是接口，实现被换成了「从数据库读」。密钥类字段加密存储。</p><p>发送链路与模板见 <a href="./messaging">消息中心</a>。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./caching">缓存与异步</a>：缓存条目与失效器</li><li><a href="./health-observability">健康检查与可观测性</a>：服务监控、探针与 OpenTelemetry</li><li><a href="./upgrade">升级与迁移</a>：版本状态、脚本与当前执行边界</li><li><a href="./../configuration">配置参考</a>：<code>appsettings</code> 全量配置节</li><li><a href="./messaging">消息中心</a>：模板与四通道发送</li><li><a href="./data-model#系统设置">数据模型</a>：相关表结构</li></ul>',45)])])}const u=e(a,[["render",r]]);export{h as __pageData,u as default};
